-- =====================================================================
-- 神通小工单：初始化全局系统菜单
-- 文件：backend/sql/mysql/20261017_init_menus.sql
-- 目标库：st_gy_mes（MySQL 8.0）
-- 依据：当前项目 system_menu 的初始化定义
-- 说明：
--   * 初始化系统管理、基础设施和监控等全局菜单。
--   * 平台管理员（super_admin）登录后读取全部启用的全局菜单。
--   * 使用 INSERT IGNORE，已存在相同菜单 ID 时跳过，不覆盖现有菜单配置。
--   * 本脚本只初始化 system_menu，不创建租户、角色或用户绑定。
--   * 可重复执行；执行后可通过脚本末尾的核对 SQL 检查启用菜单数量。
-- =====================================================================
SET NAMES utf8mb4;

START TRANSACTION;


COMMIT;

-- 执行后核对：查询当前启用的菜单数量；首次导入约 198 条，实际以数据库为准。
SELECT COUNT(*) AS enabled_menu_count
FROM system_menu
WHERE deleted = b'0' AND status = 0;

